-- ⛔ Sekvence za pevnými id (naměřeno 2026-09-14): řádky výše nesou id z produkce,
-- sekvence ale zůstala na začátku → první INSERT bez id (admin, migrace, test) na
-- čisté instanci padl na delivery_transition_rules_pkey. Posun jen DOPŘEDU
-- (max(id) i dosavadní last_value), idempotentní. Sekvence jménem přes ::regclass,
-- NE pg_get_serial_sequence(): ta pro sekvenci bez OWNED BY vrací NULL a setval(NULL)
-- by potichu nic neudělal. Týž příkaz je v heals.sql pro běžící instance.
-- Hlídá src/tests/db/sekvence-nezaostava-za-daty.runtime.test.ts.
SELECT setval(
  'public.delivery_transition_rules_id_seq'::regclass,
  GREATEST(
    (SELECT COALESCE(max(id), 0) FROM public.delivery_transition_rules),
    (SELECT COALESCE(last_value, 0) FROM pg_sequences
      WHERE schemaname = 'public' AND sequencename = 'delivery_transition_rules_id_seq'),
    1),
  EXISTS (SELECT 1 FROM public.delivery_transition_rules)
    OR EXISTS (SELECT 1 FROM pg_sequences
      WHERE schemaname = 'public' AND sequencename = 'delivery_transition_rules_id_seq' AND last_value IS NOT NULL)
);

