        "agent": "main_agent",
        "description": "Generate final response with full context",
        "next": "simplicity",
        "config": { "enable_tools": true, "max_tool_iterations": 5, "max_history": 20 }
      },
      "simplicity": {
        "type": "agent",
        "agent": "simplicity",
        "description": "Simplify response for readability",
        "next": null,
        "config": { "condition": "guardrails.useSimplicityAgent && content.length > 200", "fallthrough": true }
      }
    }
  }'::jsonb
)
ON CONFLICT (name) DO UPDATE
SET graph = EXCLUDED.graph, display_name = EXCLUDED.display_name,
    description = EXCLUDED.description,
    version = ai_workflow_definitions.version + 1, updated_at = now();

